2714	/****************************************************************************
2715	 * Name: esp32s3_dmasendsetup
2716	 *
2717	 * Description:
2718	 *   Setup to perform a write DMA.  If the processor supports a data cache,
2719	 *   then this method will also make sure that the contents of the DMA memory
2720	 *   and the data cache are coherent.  For write transfers, this may mean
2721	 *   flushing the data cache.
2722	 *
2723	 * Input Parameters:
2724	 *   dev    - An instance of the SDIO device interface
2725	 *   buffer - The memory to DMA into
2726	 *   buflen - The size of the DMA transfer in bytes
2727	 *
2728	 * Returned Value:
2729	 *   OK on success; a negated errno on failure
2730	 *
2731	 ****************************************************************************/
2732	
2733	#ifdef CONFIG_ESP32S3_SDMMC_DMA
2734	static int esp32s3_dmasendsetup(struct sdio_dev_s *dev,
2735	                                const uint8_t *buffer, size_t buflen)
2736	{
2737	  struct esp32s3_dev_s *priv = (struct esp32s3_dev_s *)dev;
2738	  uint32_t regval;
2739	
2740	  /* Don't bother with DMA if the entire transfer will fit in the TX FIFO or
2741	   * if we do not have a 4-bit wide bus.
2742	   */
2743	
2744	  DEBUGASSERT(priv != NULL);
2745	
2746	  mcinfo("buflen=%lu\n", (unsigned long)buflen);
2747	  DEBUGASSERT(buffer != NULL && buflen > 0 && ((uint32_t)buffer & 3) == 0);
2748	
2749	  /* Save the destination buffer information for use by the interrupt
2750	   * handler.
2751	   */
2752	
2753	  priv->buffer    = (uint32_t *)buffer;
2754	  priv->remaining = buflen;
2755	  priv->wrdir     = true;
2756	
2757	  /* Setup DMA descriptor list */
2758	
2759	  if (esp32s3_fill_dma_desc(priv))
2760	    {
2761	      return -ENOMEM;
2762	    }
2763	
2764	  /* Flush ints before we start */
2765	
2766	  esp32s3_putreg(SDCARD_TRANSFER_ALL, ESP32S3_SDMMC_RINTSTS);
2767	
2768	  /* Enable internal DMA, fixed burst */
2769	
2770	  regval  = esp32s3_getreg(ESP32S3_SDMMC_CTRL);
2771	  regval |= SDMMC_CTRL_INTDMA;
2772	  esp32s3_putreg(regval, ESP32S3_SDMMC_CTRL);
2773	
2774	  regval = SDMMC_BMOD_DE | SDMMC_BMOD_FB;
2775	  esp32s3_putreg(regval, ESP32S3_SDMMC_BMOD);
2776	  esp32s3_putreg(1, ESP32S3_SDMMC_PLDMND);
2777	
2778	  /* Setup DMA error interrupts */
2779	
2780	  esp32s3_config_dmaints(priv, SDCARD_DMASEND_MASK, SDCARD_DMAERROR_MASK);
2781	  return OK;
2782	}
